package com.example.api.common

/** Settings of the API, read from the environment (see .env.example). The tests build their own. */
data class Settings(
    val databaseUrl: String = "jdbc:sqlite:app.db",
    val apiKeys: List<String> = emptyList(),
) {
    companion object {
        fun fromEnvironment(): Settings {
            val env = System.getenv()
            return Settings(
                databaseUrl = env["DATABASE_URL"] ?: "jdbc:sqlite:app.db",
                apiKeys = (env["API_KEYS"] ?: "").split(",").map { it.trim() }.filter { it.isNotEmpty() },
            )
        }
    }
}

