package com.example.api.database

import com.example.api.common.Settings
import com.example.api.repository.CustomerTable
import com.example.api.repository.OrderTable
import com.example.api.repository.ProductTable
import com.zaxxer.hikari.HikariConfig
import com.zaxxer.hikari.HikariDataSource
import org.jetbrains.exposed.v1.core.DatabaseConfig
import org.jetbrains.exposed.v1.core.Table
import org.jetbrains.exposed.v1.jdbc.Database
import org.jetbrains.exposed.v1.jdbc.SchemaUtils
import org.jetbrains.exposed.v1.jdbc.transactions.transaction
import java.sql.Connection

/** The tables of the API, one per resource. */
val TABLES: Array<Table> = arrayOf(CustomerTable, ProductTable, OrderTable)

/** A database and the pool of connections it uses. */
class ApiDatabase(val database: Database, private val pool: HikariDataSource) : AutoCloseable {
    override fun close() = pool.close()
}

/**
 * Connects to the database of DATABASE_URL and creates the tables it does not have, while you develop; use
 * migrations for a real database (Model2DB writes them).
 */
fun connectDatabase(settings: Settings): ApiDatabase {
    val pool = HikariDataSource(HikariConfig().apply {
        jdbcUrl = settings.databaseUrl
        // SQLite allows one writer at a time
        maximumPoolSize = 1
    })
    // SQLite only supports serializable transactions
    val database = Database.connect(pool, databaseConfig = DatabaseConfig { defaultIsolationLevel = Connection.TRANSACTION_SERIALIZABLE })
    transaction(database) { SchemaUtils.create(*TABLES) }
    return ApiDatabase(database, pool)
}

