import org.jetbrains.exposed.v1.jdbc.update
import java.time.Instant

/** The customers table. */
object CustomerTable : Table("customers") {
    val id = long("id").autoIncrement()
    val name = text("name").nullable()
    val email = text("email").nullable()
    val password = text("password").nullable()
    val phone = text("phone").nullable()
    val address = text("address").nullable()
    val createdAt = timestamp("created_at").nullable()

    override val primaryKey = PrimaryKey(id)
}

/** Keeps customers in the database with Exposed. */
class ExposedCustomerRepository(private val database: Database) : CustomerRepository {
    override suspend fun list(query: ListQuery): ListResult<Customer> = suspendTransaction(database) {
        val select = CustomerTable.selectAll()
        for ((field, value) in query.filters) {
            when (field) {
                "id" -> select.andWhere { CustomerTable.id eq (value as Long) }
                "name" -> select.andWhere { CustomerTable.name eq (value as String) }
                "email" -> select.andWhere { CustomerTable.email eq (value as String) }
                "password" -> select.andWhere { CustomerTable.password eq (value as String) }
                "phone" -> select.andWhere { CustomerTable.phone eq (value as String) }
                "createdAt" -> select.andWhere { CustomerTable.createdAt eq (value as Instant) }
            }
        }
        val total = select.count()
        val sorted = when (query.sortField) {
            "id" -> CustomerTable.id
            "name" -> CustomerTable.name
            "email" -> CustomerTable.email
            "password" -> CustomerTable.password
            "phone" -> CustomerTable.phone
            "createdAt" -> CustomerTable.createdAt
            else -> null
        }
        // Items without a value go last, whatever the order; the key breaks ties
        if (sorted != null) select.orderBy(sorted, if (query.descending) SortOrder.DESC_NULLS_LAST else SortOrder.ASC_NULLS_LAST)
        select.orderBy(CustomerTable.id, SortOrder.ASC)
        if (query.limit != null) select.limit(query.limit).offset(query.offset.toLong())
        ListResult(select.map(::toItem), total)
    }

    override suspend fun get(key: Long): Customer? = suspendTransaction(database) {
        CustomerTable.selectAll().where { CustomerTable.id eq key }.singleOrNull()?.let(::toItem)
    }

    override suspend fun add(item: Customer): Customer {
        val key = suspendTransaction(database) {
            CustomerTable.insert { fill(it, item) } get CustomerTable.id
        }
        // Read back, so the answer has what the database keeps
        return get(key)!!
    }

    override suspend fun update(item: Customer): Customer {
        suspendTransaction(database) { CustomerTable.update({ CustomerTable.id eq item.id }) { fill(it, item) } }
        return get(item.id)!!
    }

    override suspend fun delete(key: Long) {
        suspendTransaction(database) { CustomerTable.deleteWhere { CustomerTable.id eq key } }
    }

    /** Every column but the key takes the value of the item. */
    private fun fill(row: UpdateBuilder<*>, item: Customer) {
        row[CustomerTable.name] = item.name
        row[CustomerTable.email] = item.email
        row[CustomerTable.password] = item.password
        row[CustomerTable.phone] = item.phone
        row[CustomerTable.address] = item.address?.let { JsonFormat.encodeToString(Address.serializer(), it) }
        row[CustomerTable.createdAt] = item.createdAt
    }

    private fun toItem(row: ResultRow) = Customer(
        id = row[CustomerTable.id],
        name = row[CustomerTable.name],
        email = row[CustomerTable.email],
        password = row[CustomerTable.password],
        phone = row[CustomerTable.phone],
        address = row[CustomerTable.address]?.let { JsonFormat.decodeFromString(Address.serializer(), it) },
        createdAt = row[CustomerTable.createdAt],
    )
}

